// Consolidated utilities with more robust parsing and simpler helpers.
// Maintains original functionality and Redux-Saga best practices.

import { ResultType, StepResponse } from '@txp-core/runtime';
import { put } from 'redux-saga/effects';
import {
  PaymentChargesTableAction,
  paymentTableSelectors
} from '@txp-core/payment-transactions-table';
import { select } from '@txp-core/basic-utils';
import type { CreditChargesPaymentTypes } from '@txp-core/payment-transactions-table/dist/paymentTableStateTypes';

const DECIMALS = 2;

// ---------- Utilities ----------
// Single, more robust parser consolidating number normalization and clamping/rounding.
const parseAmount = (
  value: unknown,
  { fallback = 0, nonNegative = false, decimals }: { fallback?: number; nonNegative?: boolean; decimals?: number } = {}
): number => {
  // Early exits for nullish and booleans
  if (value == null || typeof value === 'boolean') return fallback;

  // Numbers: ensure finite
  if (typeof value === 'number') {
    const n = Number.isFinite(value) ? value : fallback;
    const clamped = nonNegative && n < 0 ? 0 : n;
    return typeof decimals === 'number' ? roundTo(clamped, decimals) : clamped;
  }

  // Attempt string-like normalization for all other types
  let s: string;
  try {
    s = String((value as any)?.toString?.() ?? '');
  } catch {
    return fallback;
  }

  s = s.trim();
  if (!s) return fallback;

  // Normalize unicode minus variants
  s = s.replace(/[−–—]/g, '-');

  // Parentheses negative: (123.45) -> -123.45
  const parenNegative = /^\(.*\)$/.test(s);
  if (parenNegative) s = s.slice(1, -1).trim();

  // Remove currency symbols and letters; keep digits, separators, signs, and spaces (incl NBSP)
  s = s.replace(/[^\d.,+\-\s\u00A0]/g, '');
  // Remove spaces (including NBSP)
  s = s.replace(/[\s\u00A0]/g, '');

  // If both '.' and ',' exist, assume the rightmost is decimal sep
  if (s.includes('.') && s.includes(',')) {
    const lastDot = s.lastIndexOf('.');
    const lastComma = s.lastIndexOf(',');
    const decSep = lastDot > lastComma ? '.' : ',';
    const thouSep = decSep === '.' ? ',' : '.';
    s = s.split(thouSep).join('');
    s = s.split(decSep).join('.');
  } else if (s.includes(',') && !s.includes('.')) {
    // Heuristic: if 1–2 digits after last comma, treat as decimal; else thousands
    const last = s.lastIndexOf(',');
    const after = s.slice(last + 1);
    const digitsAfter = (after.match(/\d/g) || []).length;
    s = digitsAfter >= 1 && digitsAfter <= 2 ? s.replace(/,/g, '.'): s.replace(/,/g, '');
  } else if (s.includes('.')) {
    if ((s.match(/\./g) || []).length > 1) {
      const last = s.lastIndexOf('.');
      s = s.slice(0, last).replace(/\./g, '') + '.' + s.slice(last + 1);
    }
  }

  // Extract a single leading sign
  const signMatch = s.match(/^[+\-]+/);
  const sign = signMatch ? (signMatch[0].includes('-') ? '-' : '+') : '';
  s = s.slice(signMatch ? signMatch[0].length : 0);

  // Keep only digits and a single dot
  s = s.replace(/[^\d.]/g, '');
  if ((s.match(/\./g) || []).length > 1) return fallback;

  let normalized = (sign || '') + s;
  if (parenNegative && !normalized.startsWith('-')) normalized = '-' + normalized;

  if (!/^[+\-]?\d*\.?\d+$/.test(normalized)) return fallback;

  const n = Number(normalized);
  if (!Number.isFinite(n)) return fallback;

  let out = n;
  if (nonNegative && out < 0) out = 0;
  if (typeof decimals === 'number') out = roundTo(out, decimals);
  return out;
};

const roundTo = (n: number, decimals = DECIMALS): number => {
  const factor = 10 ** decimals;
  return Math.round((n + Number.EPSILON) * factor) / factor;
};

const formatAmount = (n: number, decimals = DECIMALS): string => {
  const fixed = n.toFixed(decimals);
  const trimmed = fixed.replace(/\.0+$/, '.0').replace(/\.?0+$/, '');
  return trimmed === '' ? '0' : trimmed;
};

const clampNonNegative = (n: number): number => (n < 0 ? 0 : n);

// ---------- Saga ----------
export function* outstandingTransactionsHandler(): Generator<any, StepResponse, any> {
  try {
    const creditTableLines: CreditChargesPaymentTypes[] =
      (yield* select(paymentTableSelectors.getCredits)) ?? [];

    const totalOfChargesTableRaw: unknown =
      yield* select(paymentTableSelectors.getTotalOfChargesTable);

    // Normalize inputs with consolidated parser
    let remaining = parseAmount(totalOfChargesTableRaw, { fallback: 0, nonNegative: true, decimals: DECIMALS });

    // Fast path: nothing to do
    if (!Array.isArray(creditTableLines) || creditTableLines.length === 0) {
      return { result: ResultType.SUCCESS };
    }

    let didChange = false;

    const updatedCreditTable: CreditChargesPaymentTypes[] = creditTableLines.map((credit) => {
      const next: CreditChargesPaymentTypes = { ...credit };

      // A row is considered checked if linkedPaymentAmount is a non-empty string (including "0")
      const isChecked = String(credit?.linkedPaymentAmount ?? '') !== '';
      if (!isChecked) return next;

      const openBalance = clampNonNegative(
        parseAmount(credit?.openBalance, { fallback: 0, nonNegative: true, decimals: DECIMALS })
      );

      if (remaining <= 0) {
        if (next.linkedPaymentAmount !== '') {
          next.linkedPaymentAmount = '';
          didChange = true;
        }
        return next;
      }

      const allocation = Math.min(openBalance, remaining);
      const formatted = formatAmount(allocation, DECIMALS);

      if (next.linkedPaymentAmount !== formatted) {
        next.linkedPaymentAmount = formatted;
        didChange = true;
      }

      remaining = roundTo(remaining - allocation, DECIMALS);
      if (remaining < 0) remaining = 0;

      return next;
    });

    if (didChange) {
      yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCreditTable));
    }

    return { result: ResultType.SUCCESS };
  } catch (err) {
    return {
      result: ResultType.FAILURE,
      message: 'Unable to allocate outstanding transactions'
    } as StepResponse;
  }
}
