// ---------- Utility / Data Processing ----------
static vector<string> tokenize(const string& text) {
    vector<string> tokens;
    string cur;
    for (char c : text) {
        if (isalpha(static_cast<unsigned char>(c))) cur.push_back(static_cast<char>(tolower(c)));
        else if (!cur.empty()) { tokens.push_back(cur); cur.clear(); }
    }
    if (!cur.empty()) tokens.push_back(cur);
    return tokens;
}

// ---------- Encapsulated Value Object with Operator Overloading ----------
class Dimension {
private:
    double width_{}, height_{}, depth_{};
public:
    Dimension() = default;
    Dimension(double w, double h, double d) : width_(w), height_(h), depth_(d) {}

    double width() const { return width_; }
    double height() const { return height_; }
    double depth() const { return depth_; }

    double volume() const { return width_ * height_ * depth_; }

    Dimension operator+(const Dimension& other) const {
        return Dimension(width_ + other.width_, height_ + other.height_, depth_ + other.depth_);
    }
    Dimension operator*(double scalar) const { return Dimension(width_ * scalar, height_ * scalar, depth_ * scalar); }
    friend Dimension operator*(double s, const Dimension& d) { return d * s; }

    friend ostream& operator<<(ostream& os, const Dimension& d) {
        os << fixed << setprecision(2)
           << "Dimension(" << d.width_ << " x " << d.height_ << " x " << d.depth_
           << ", vol=" << d.volume() << ")";
        return os;
    }
};

// ---------- Abstract Base Class and Derived Types (Inheritance + Polymorphism) ----------
class Exhibit {
private:
    string name_;
    int year_{};
    vector<int> ratings_; // 1..5
protected:
    Exhibit(string name, int year) : name_(std::move(name)), year_(year) {}
public:
    virtual ~Exhibit() = default;

    const string& name() const { return name_; }
    int year() const { return year_; }

    // Method overloading
    void addRating(int r) {
        if (r < 1 || r > 5) throw out_of_range("Rating must be 1..5");
        ratings_.push_back(r);
    }
    void addRating(const vector<int>& rs) { for (int r : rs) addRating(r); }
    void addRating(initializer_list<int> rs) { for (int r : rs) addRating(r); }

    optional<double> averageRating() const {
        if (ratings_.empty()) return nullopt;
        double sum = accumulate(ratings_.begin(), ratings_.end(), 0.0);
        return sum / ratings_.size();
    }

    virtual void display() const = 0;
    virtual string kind() const = 0;
    virtual unique_ptr<Exhibit> clone() const = 0;

    bool operator<(const Exhibit& other) const {
        if (name_ != other.name_) return name_ < other.name_;
        return year_ < other.year_;
    }
    bool operator==(const Exhibit& other) const {
        return name_ == other.name_ && year_ == other.year_ && kind() == other.kind();
    }

    friend ostream& operator<<(ostream& os, const Exhibit& e) {
        os << "[" << e.kind() << "] " << e.name() << " (" << e.year() << ")";
        if (auto avg = e.averageRating()) os << " avg=" << fixed << setprecision(2) << *avg;
        else os << " avg=n/a";
        return os;
    }
};

