Notes:
- The uniformCrossover function is correct and self-contained (no stray references or unfinished alternatives).
- After crossover/mutation, the projection function enforces both the sum-to-1 constraint and per-asset bounds via a bisection-based approach, keeping candidates feasible.

Step-by-step plan (aligned with the C# implementation)
- Model each interval as a half-open range [StartIncl, EndExl).
- Keep a helper to check if a range is empty (StartIncl >= EndExl).
- Normalize the input so we always consider the range that starts earlier as left, and the other as right (lexicographic by StartIncl then EndExl).
- If the ranges are disjoint or only touch (left.EndExl <= right.StartIncl), return the two non-empty ranges in order.
- If they overlap:
  - before: [left.StartIncl, right.StartIncl) if left starts before right
  - overlap: [max(left.StartIncl, right.StartIncl), min(left.EndExl, right.EndExl)) — guaranteed non-empty when in overlap branch
  - after: [overlapEnd, laterEnd) where laterEnd = max(left.EndExl, right.EndExl), if overlapEnd < laterEnd
- Return only non-empty segments, in left-to-right order.

// C# implementation

using System;
using System.Collections.Generic;

public readonly record struct Range(long StartIncl, long EndExl)
{
    // Half-open interval: [StartIncl, EndExl)
    public bool IsEmpty => StartIncl >= EndExl;

    public override string ToString() => $"[{StartIncl},{EndExl})";
}

public static class RangeUtils
{
    /// <summary>
    /// Split two half-open ranges [StartIncl, EndExl) into up to three ordered subranges:
    /// - The part before the overlap (if any)
    /// - The overlap itself (if any)
    /// - The part after the overlap (if any)
    ///
    /// If the ranges are disjoint or only touch, returns the two non-empty ranges in order.
    /// Only non-empty subranges are returned.
    /// </summary>
    public static List<Range> SplitByOverlap(Range r1, Range r2)
    {
        // Normalize so that 'left' starts first (lexicographic by start, then end)
        Range left, right;
        if (r1.StartIncl < r2.StartIncl ||
            (r1.StartIncl == r2.StartIncl && r1.EndExl <= r2.EndExl))
        {
            left = r1;
            right = r2;
        }
        else
        {
            left = r2;
            right = r1;
        }

        var result = new List<Range>(capacity: 3);

        // If disjoint or just touching, there is no overlap
        if (left.EndExl <= right.StartIncl)
        {
            if (!left.IsEmpty) result.Add(left);
            if (!right.IsEmpty) result.Add(right);
            return result;
        }

        // They overlap
        long overlapStart = Math.Max(left.StartIncl, right.StartIncl); // == right.StartIncl here when left starts earlier
        long overlapEnd = Math.Min(left.EndExl, right.EndExl);

        // Part before overlap
        if (left.StartIncl < overlapStart)
        {
            var before = new Range(left.StartIncl, overlapStart);
            if (!before.IsEmpty) result.Add(before);
        }

        // Overlap itself
        if (overlapStart < overlapEnd)
        {
            result.Add(new Range(overlapStart, overlapEnd));
        }

        // Part after overlap (extends to the later end)
        long laterEnd = Math.Max(left.EndExl, right.EndExl);
        if (overlapEnd < laterEnd)
        {
            var after = new Range(overlapEnd, laterEnd);
            if (!after.IsEmpty) result.Add(after);
        }

        return result;
    }
}

// Example usage and quick checks
public static class Program
{
    public static void Main()
    {
        // 1) Overlapping partially: [1,10) and [5,15) -> [1,5), [5,10), [10,15)
        Dump(RangeUtils.SplitByOverlap(new Range(1, 10), new Range(5, 15)));

        // 2) One inside the other: [1,10) and [3,7) -> [1,3), [3,7), [7,10)
        Dump(RangeUtils.SplitByOverlap(new Range(1, 10), new Range(3, 7)));

        // 3) Identical: [2,5) and [2,5) -> [2,5)
        Dump(RangeUtils.SplitByOverlap(new Range(2, 5), new Range(2, 5)));

        // 4) Disjoint: [1,3) and [5,7) -> [1,3), [5,7)
        Dump(RangeUtils.SplitByOverlap(new Range(1, 3), new Range(5, 7)));

        // 5) Touching (abutting): [1,3) and [3,7) -> [1,3), [3,7) (no overlap)
        Dump(RangeUtils.SplitByOverlap(new Range(1, 3), new Range(3, 7)));
    }

    private static void Dump(List<Range> ranges)
    {
        Console.WriteLine(string.Join(" ", ranges));
    }
}

Notes
- The implementation strictly uses half-open intervals [StartIncl, EndExl).
- It preserves ordering from smallest start to largest end and returns only non-empty segments.
- Behavior summary:
  - 3 segments when there’s a genuine overlap and both sides extend past the overlap.
  - 2 segments when disjoint or just touching (no overlap).
  - 1 segment when identical or when one fully covers the other without side parts.

